@namespace sv_dc48d0cb0e1e4ce7a0fa6ec8e979f59f.Components.Pages.Settings
@using sv_dc48d0cb0e1e4ce7a0fa6ec8e979f59f.Services

<div class="settings-section">
    <h3>Appearance</h3>

    @if (_successMessage is not null)
    {
        <div class="alert alert-success alert-dismissible fade show" role="alert">
            @_successMessage
            <button type="button" class="btn-close" @onclick="() => _successMessage = null"></button>
        </div>
    }

    <!-- Theme -->
    <div class="mb-4">
        <h5>Theme</h5>
        @foreach (var theme in new[] { "Light", "Dark", "System" })
        {
            <div class="form-check">
                <input class="form-check-input" type="radio" name="theme" id="@($"theme-{theme}")"
                       value="@theme" checked="@(_theme == theme)"
                       @onchange="() => _theme = theme" />
                <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
            </div>
        }
    </div>

    <!-- Font Size -->
    <div class="mb-4">
        <h5>Font Size</h5>
        @foreach (var size in new[] { "Small", "Medium", "Large" })
        {
            <div class="form-check">
                <input class="form-check-input" type="radio" name="fontSize" id="@($"fs-{size}")"
                       value="@size" checked="@(_fontSize == size)"
                       @onchange="() => _fontSize = size" />
                <label class="form-check-label" for="@($"fs-{size}")">@size</label>
            </div>
        }
    </div>

    <!-- Language -->
    <div class="mb-4">
        <h5>Language</h5>
        <select class="form-select" @bind="_language">
            <option value="English">English</option>
            <option value="Spanish">Spanish</option>
            <option value="French">French</option>
            <option value="German">German</option>
            <option value="Japanese">Japanese</option>
        </select>
    </div>

    <!-- Compact Mode -->
    <div class="mb-4">
        <div class="form-check form-switch">
            <input class="form-check-input" type="checkbox" id="compactMode" @bind="_compactMode" />
            <label class="form-check-label" for="compactMode">Compact Mode</label>
        </div>
    </div>

    <!-- Live Preview -->
    <div class="mb-4">
        <h5>Preview</h5>
        <div class="border rounded p-3" style="@PreviewStyle">
            <h6 style="@PreviewFontStyle">Sample Heading</h6>
            <p style="@PreviewFontStyle" class="@(_compactMode ? "mb-1" : "mb-3")">
                This is how your content will look with the selected appearance settings.
            </p>
            <button class="btn btn-sm btn-primary">Sample Button</button>
        </div>
    </div>

    <button class="btn btn-primary" @onclick="SaveAsync">Save</button>
</div>

@code {
    [Parameter] public AppearanceSettings? Settings { get; set; }
    [Parameter] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;
    private string? _successMessage;

    protected override void OnParametersSet()
    {
        if (Settings is not null)
        {
            _theme = Settings.Theme;
            _fontSize = Settings.FontSize;
            _language = Settings.Language;
            _compactMode = Settings.CompactMode;
        }
    }

    private string PreviewStyle => _theme switch
    {
        "Dark" => "background-color:#1e1e1e;color:#e0e0e0;",
        "Light" => "background-color:#ffffff;color:#212529;",
        _ => "background-color:#f8f9fa;color:#212529;"
    };

    private string PreviewFontStyle => _fontSize switch
    {
        "Small" => "font-size:0.85rem;",
        "Large" => "font-size:1.25rem;",
        _ => "font-size:1rem;"
    };

    private async Task SaveAsync()
    {
        var updated = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await OnSave.InvokeAsync(updated);
        _successMessage = "Appearance settings saved!";
    }
}

@page "/settings"
@namespace sv_dc48d0cb0e1e4ce7a0fa6ec8e979f59f.Components.Pages.Settings
@using sv_dc48d0cb0e1e4ce7a0fa6ec8e979f59f.Services
@rendermode InteractiveServer
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-layout">
    <SettingsSidebar ActiveSection="@_activeSection" OnSectionSelected="SetActiveSection" />

    <div class="settings-content">
        @switch (_activeSection)
        {
            case "Profile":
                <ProfileSection Profile="@_profile" OnSave="SaveProfileAsync" />
                break;
            case "Notifications":
                <NotificationsSection Prefs="@_notificationPrefs" OnSave="SaveNotificationsAsync" />
                break;
            case "Security":
                <SecuritySection Security="@_security"
                                 OnChangePassword="HandleChangePasswordAsync"
                                 OnRevokeSession="HandleRevokeSessionAsync" />
                break;
            case "Appearance":
                <AppearanceSection Settings="@_appearance" OnSave="SaveAppearanceAsync" />
                break;
        }
    </div>
</div>

@code {
    private string _activeSection = "Profile";
    private UserProfile? _profile;
    private NotificationPrefs? _notificationPrefs;
    private SecuritySettings? _security;
    private AppearanceSettings? _appearance;

    protected override async Task OnInitializedAsync()
    {
        await LoadSectionDataAsync();
    }

    private async Task LoadSectionDataAsync()
    {
        _profile = await SettingsService.GetProfileAsync();
        _notificationPrefs = await SettingsService.GetNotificationPrefsAsync();
        _security = await SettingsService.GetSecuritySettingsAsync();
        _appearance = await SettingsService.GetAppearanceAsync();
    }

    private void SetActiveSection(string section)
    {
        _activeSection = section;
    }

    private async Task SaveProfileAsync(UserProfile profile)
    {
        await SettingsService.SaveProfileAsync(profile);
        _profile = profile;
    }

    private async Task SaveNotificationsAsync(NotificationPrefs prefs)
    {
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        _notificationPrefs = prefs;
    }

    private async Task HandleChangePasswordAsync(string payload)
    {
        var parts = payload.Split('|', 2);
        await SettingsService.ChangePasswordAsync(parts[0], parts[1]);
        _security = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task HandleRevokeSessionAsync(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        _security = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task SaveAppearanceAsync(AppearanceSettings settings)
    {
        await SettingsService.SaveAppearanceAsync(settings);
        _appearance = settings;
    }
}

