/* Settings Dashboard Layout */
.settings-layout {
    display: flex;
    min-height: calc(100vh - 80px);
    gap: 0;
}

.settings-sidebar {
    width: 220px;
    min-width: 220px;
    background-color: #f8f9fa;
    border-right: 1px solid #dee2e6;
    padding: 1.5rem 0;
}

